    required this.provider,
    required this.title,
    required this.status,
    this.activity,
    this.origin,
    this.project,
    this.workingDirectories,
    this.annotations,
    required this.resource,
    required this.createdAt,
    required this.modifiedAt,
    this.changes,
    this.meta,
    this.chats,
    this.defaultChat,
  });

  /// Decodes a [SessionSummary] from JSON.
  factory SessionSummary.fromJson(JsonMap json) => SessionSummary(
    provider: (json['provider'] as String),
    title: (json['title'] as String),
    status: SessionStatus((json['status'] as num).toInt()),
    activity: json['activity'] == null ? null : (json['activity'] as String),
    origin: json['origin'] == null
        ? null
        : AutomationSessionOrigin.fromJson(json['origin'] as JsonMap),
    project: json['project'] == null
        ? null
        : ProjectInfo.fromJson(json['project'] as JsonMap),
    workingDirectories: json['workingDirectories'] == null
        ? null
        : [
            for (final e0 in json['workingDirectories'] as List<Object?>)
              (e0 as String),
          ],
    annotations: json['annotations'] == null
        ? null
        : AnnotationsSummary.fromJson(json['annotations'] as JsonMap),
    resource: (json['resource'] as String),
    createdAt: (json['createdAt'] as String),
    modifiedAt: (json['modifiedAt'] as String),
    changes: json['changes'] == null
        ? null
        : ChangesSummary.fromJson(json['changes'] as JsonMap),
    meta: json['_meta'] == null ? null : (json['_meta'] as JsonMap),
    chats: json['chats'] == null
        ? null
        : [
            for (final e0 in json['chats'] as List<Object?>)
              SessionChatSummary.fromJson(e0 as JsonMap),
          ],
    defaultChat: json['defaultChat'] == null
        ? null
        : (json['defaultChat'] as String),
  );

  /// Agent provider ID
  final String provider;

  /// Session title
  final String title;

  /// Current session status
  final SessionStatus status;

  /// Human-readable description of what the session is currently doing
  final String? activity;

  /// Durable [AutomationSessionOrigin], when an automation run created this session.
  final AutomationSessionOrigin? origin;

  /// Server-owned project for this session
  final ProjectInfo? project;

  /// The working directories the session's agent has tool access to, as
  /// maintained by working-directory actions. Directories are equal peers except
  /// when the agent advertises
  /// `MultipleWorkingDirectoriesCapability.immutablePrimary` without
  /// `MultipleWorkingDirectoriesCapability.primaryReplacement` (the first
  /// entry is then a fixed process root), or advertises `primaryReplacement`
