    lifecycle: TerminalLifecycleState.fromJson(json['lifecycle'] as JsonMap),
    claim: TerminalClaim.fromJson(json['claim'] as JsonMap),
    supportsCommandDetection: json['supportsCommandDetection'] == null
        ? null
        : (json['supportsCommandDetection'] as bool),
    isPty: json['isPty'] == null ? null : (json['isPty'] as bool),
  );

  /// Human-readable terminal title
  final String title;

  /// Current working directory of the terminal process
  final String? cwd;

  /// Terminal width in columns
  final int? cols;

  /// Terminal height in rows
  final int? rows;

  /// Typed content parts, replacing the flat `content: string`.
  ///
  /// Naive consumers that only need the raw VT stream can reconstruct it with:
  ///   `content.map(p => p.type === 'command' ? p.output : p.value).join('')`
  ///
  /// Consumers that need command boundaries can filter by part type.
  final List<TerminalContentPart> content;

  /// Current terminal process lifecycle.
  final TerminalLifecycleState lifecycle;

  /// Who currently holds this terminal
  final TerminalClaim claim;

