    cols: identical(cols, _unset) ? this.cols : cols as int?,
    rows: identical(rows, _unset) ? this.rows : rows as int?,
    content: content ?? this.content,
    lifecycle: lifecycle ?? this.lifecycle,
    claim: claim ?? this.claim,
    supportsCommandDetection: identical(supportsCommandDetection, _unset)
        ? this.supportsCommandDetection
        : supportsCommandDetection as bool?,
