  @override
  int get hashCode => Object.hashAll([runtimeType, _deep.hash(review)]);

  @override
  String toString() => 'ChangesetCapabilities(review: $review)';
}

/// Full state for a single changeset, returned when a client subscribes to
/// an expanded changeset URI.
