    ChangesetStatus? status,
    ErrorInfo? error,
    List<ChangesetFile>? files,
    List<ChangesetOperation>? operations,
  })
  get copyWith => _copyWith;

  ChangesetState _copyWith({
    ChangesetStatus? status,
    Object? error = _unset,
    List<ChangesetFile>? files,
    Object? operations = _unset,
  }) => ChangesetState(
    status: status ?? this.status,
    error: identical(error, _unset) ? this.error : error as ErrorInfo?,
    files: files ?? this.files,
    operations: identical(operations, _unset)
        ? this.operations
        : operations as List<ChangesetOperation>?,
  );

  /// Encodes this [ChangesetState] as JSON.
  JsonMap toJson() => {
    'status': status.toJson(),
    if (error case final v?) 'error': v.toJson(),
    'files': [for (final e0 in files) e0.toJson()],
    if (operations case final v?)
