/// One file entry within a [ChangesetState].
@immutable
final class ChangesetFile {
  /// Creates a [ChangesetFile].
  const ChangesetFile({
    required this.id,
    required this.edit,
    this.reviewed,
    this.meta,
  });

  /// Decodes a [ChangesetFile] from JSON.
  factory ChangesetFile.fromJson(JsonMap json) => ChangesetFile(
    id: (json['id'] as String),
    edit: FileEdit.fromJson(json['edit'] as JsonMap),
    reviewed: json['reviewed'] == null ? null : (json['reviewed'] as bool),
    meta: json['_meta'] == null ? null : (json['_meta'] as JsonMap),
