    String? id,
    FileEdit? edit,
    bool? reviewed,
    JsonMap? meta,
  })
  get copyWith => _copyWith;

  ChangesetFile _copyWith({
    String? id,
    FileEdit? edit,
    Object? reviewed = _unset,
    Object? meta = _unset,
